\copy (select s.sheet_id, s.ticker, (s.generated_at at time zone 'Asia/Seoul')::date gd, (s.provenance_json->>'conviction')::numeric conv, p.entry_date, p.exit_date, p.holding_days, p.pnl_pct, p.exit_reason, (select close_price::numeric from daily_prices where stock_code='069500' and price_date<=p.entry_date order by price_date desc limit 1) b0, (select close_price::numeric from daily_prices where stock_code='069500' and price_date<=p.exit_date order by price_date desc limit 1) b1 from position_sheets s join paper_outcomes p using(sheet_id) where s.generated_at >= '2026-08-15' and p.exit_date is not null and p.pnl_pct is not null order by s.ticker, s.generated_at) to stdout with csv header
